// The user id is the connection's, never the frame's: validation already dropped any the frame carried.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  {limit, before}: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(({sessionId, createdAt, updatedAt, entryCount}) => ({
        sessionId,
        createdAt: createdAt.toISOString(),
        updatedAt: updatedAt.toISOString(),
        entryCount,
      })),
    });
  } catch (error) {
    log.error('ws', 'listing sessions failed', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
